import org.apache.http.client.methods.CloseableHttpResponse;
import org.apache.http.client.methods.HttpUriRequest;
import org.apache.http.impl.client.CloseableHttpClient;
import org.junit.Test;

import java.lang.reflect.Field;
import java.util.concurrent.atomic.AtomicBoolean;

import org.mockito.MockedStatic;
import org.mockito.Mockito;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.*;

/**
 * Tests for {@link HttpHeartbeatSender}.
 * Verifies that the status code is read BEFORE closing the response.
 */
public class HttpHeartbeatSenderTest {

    private static final String TEST_HOST = "127.0.0.1";
    private static final int TEST_PORT = 8080;

    /**
     * Test that sendHeartbeat() reads status code BEFORE closing the response.
     * 
     * The bug: response.close() is called on line 100, then getStatusLine().getStatusCode()
     * is called on line 101 on the already-closed response. This violates the CloseableHttpResponse
     * contract and causes IllegalStateException (undefined behavior after close).
     * 
     * The correct behavior: status code should be read BEFORE close() is called.
     * 
     * This test creates a mock response that throws IllegalStateException when
     * getStatusLine() is called after close(). On buggy code, sendHeartbeat() will throw.
     * On fixed code, sendHeartbeat() will return normally (status read before close).
     */
    @Test
    public void testSendHeartbeatShouldReadStatusBeforeClose() throws Exception {
        // Set up mock response that simulates Apache HttpClient behavior:
        // calling getStatusLine() after close() throws IllegalStateException
        AtomicBoolean closed = new AtomicBoolean(false);
        StatusLine statusLine = mock(StatusLine.class);
        when(statusLine.getStatusCode()).thenReturn(200);

        CloseableHttpResponse mockResponse = mock(CloseableHttpResponse.class);
        doAnswer(new org.mockito.stubbing.Answer<Void>() {
            @Override
            public Void answer(org.mockito.invocation.InvocationOnMock invocation) {
                closed.set(true);
                return null;
            }
        }).when(mockResponse).close();

        // After close, getStatusLine() throws (simulating real CloseableHttpResponse behavior)
        when(mockResponse.getStatusLine()).thenAnswer(new org.mockito.stubbing.Answer<StatusLine>() {
            @Override
            public StatusLine answer(org.mockito.invocation.InvocationOnMock invocation) {
                if (closed.get()) {
                    throw new IllegalStateException("Cannot access StatusLine after response has been closed");
                }
                return statusLine;
            }
        });

        // Set up mock client to return our mock response
        CloseableHttpClient mockClient = mock(CloseableHttpClient.class);
        when(mockClient.execute(any(HttpUriRequest.class))).thenReturn(mockResponse);

        // Create HttpHeartbeatSender and inject dependencies via reflection
        HttpHeartbeatSender sender = createSenderWithMockClient(mockClient);

        // Mock static dependencies used in sendHeartbeat()
        try (MockedStatic<TransportConfig> tcMock = mockStatic(TransportConfig.class);
             MockedStatic<AppNameUtil> appMock = mockStatic(AppNameUtil.class);
             MockedStatic<HostNameUtil> hostMock = mockStatic(HostNameUtil.class);
             MockedStatic<PidUtil> pidMock = mockStatic(PidUtil.class);
             MockedStatic<SentinelConfig> scMock = mockStatic(SentinelConfig.class)) {

            tcMock.when(() -> TransportConfig.getHeartbeatApiPath()).thenReturn("/sentinel/heartbeat");
            tcMock.when(() -> TransportConfig.getHeartbeatClientIp()).thenReturn("127.0.0.1");
