/**
 * Tests for thread-safety of token bucket implementations.
 *
 * This test verifies that concurrent calls to tryConsume() do not allow
 * more tokens to be consumed than are actually available in the bucket.
 */
public class AbstractTokenBucketConcurrentTest {

    /**
     * Test that DefaultTokenBucket (which inherits the unsynchronized
     * tryConsume from AbstractTokenBucket) does not allow over-consumption
     * when multiple threads try to consume concurrently.
     *
     * Expected correct behavior: no more than maxTokenNum tokens should
     * ever be consumed from a full bucket, even with concurrent access.
     *
     * Runs multiple iterations to increase the probability of hitting
     * the race condition in the read-check-update on volatile field.
     */
    @Test
    public void testDefaultTokenBucketConcurrentConsumeNoOverConsumption() throws InterruptedException {
        // Run many iterations to make the race condition almost certain to manifest
        boolean overConsumed = false;
        String lastDetail = "";

        for (int iteration = 0; iteration < 100; iteration++) {
            try (MockedStatic<com.alibaba.csp.sentinel.util.TimeUtil> mockedTime = Mockito.mockStatic(com.alibaba.csp.sentinel.util.TimeUtil.class)) {
                long fixedTime = 1000L;
                mockedTime.when(com.alibaba.csp.sentinel.util.TimeUtil::currentTimeMillis).thenReturn(fixedTime);

                long maxTokens = 5;
                DefaultTokenBucket bucket = new DefaultTokenBucket(1, maxTokens, true, 1000L);

                // Many threads competing for few tokens to maximize race probability
                int threadCount = 100;
                AtomicInteger successCount = new AtomicInteger(0);
                CountDownLatch startLatch = new CountDownLatch(1);
                CountDownLatch endLatch = new CountDownLatch(threadCount);

                Thread[] threads = new Thread[threadCount];
                for (int i = 0; i < threadCount; i++) {
                    threads[i] = new Thread(() -> {
                        try {
                            startLatch.await();
                            if (bucket.tryConsume(1)) {
                                successCount.incrementAndGet();
                            }
                        } catch (InterruptedException e) {
                            Thread.currentThread().interrupt();
                        } finally {
                            endLatch.countDown();
                        }
                    });
                    threads[i].start();
                }

                startLatch.countDown();
                endLatch.await();

                int successes = successCount.get();
                long remaining = bucket.getCurrentTokenNum();

                if (successes > maxTokens) {
                    overConsumed = true;
                    lastDetail = String.format("Iteration %d: over-consumption: %d succeeded out of %d tokens, remaining=%d",
                            iteration, successes, maxTokens, remaining);
                    break;
                }
            }
        }

        if (!overConsumed) {
