package com.alibaba.csp.sentinel.transport.heartbeat.client;

import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;

import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.nio.charset.Charset;

import org.junit.Test;

/**
 * Tests for {@link SimpleHttpResponseParser}.
 */
public class SimpleHttpResponseParserTest {

    private static final Charset UTF8 = Charset.forName("utf-8");

    @Test
    public void parseSmallResponseWhereBodyFitsInSameRead() throws IOException {
        // Small response where entire body arrives in the same read as headers.
        // Content-Length matches body exactly; no trailing data.
        String response = "HTTP/1.1 200 OK\r\n"
                        + "Content-Length: 2\r\n"
                        + "\r\n"
                        + "OK";
        SimpleHttpResponseParser parser = new SimpleHttpResponseParser();
        SimpleHttpResponse result = parser.parse(new ByteArrayInputStream(response.getBytes(UTF8)));
        assertNotNull(result);
        byte[] body = result.getBody();
        assertNotNull(body);
        assertArrayEquals("OK".getBytes(UTF8), body);
    }

    @Test
    public void parseSmallResponseWithTrailingDataInSameRead() throws IOException {
        // Body arrives in the same read as headers, and there is trailing data
        // after the body (e.g., from TCP coalescing of pipelined responses).
        // The parser should read exactly Content-Length bytes and NOT throw.
        String response = "HTTP/1.1 200 OK\r\n"
                        + "Content-Length: 2\r\n"
                        + "\r\n"
                        + "OK\r\n"
                        + "HTTP/1.1 200 OK"; // trailing bytes from next response
        SimpleHttpResponseParser parser = new SimpleHttpResponseParser();
        SimpleHttpResponse result = parser.parse(new ByteArrayInputStream(response.getBytes(UTF8)));
        assertNotNull(result);
        byte[] body = result.getBody();
        assertNotNull(body);
        assertArrayEquals("OK".getBytes(UTF8), body);
    }

    @Test
    public void parseEmptyBodyResponse() throws IOException {
        // Content-Length: 0, no body
        String response = "HTTP/1.1 200 OK\r\n"
                        + "Content-Length: 0\r\n"
                        + "\r\n";
        SimpleHttpResponseParser parser = new SimpleHttpResponseParser();
        SimpleHttpResponse result = parser.parse(new ByteArrayInputStream(response.getBytes(UTF8)));
        assertNotNull(result);
    }

    @Test
    public void parseBodyArrivingAfterHeaders() throws IOException {
        // Headers arrive first, body arrives in a subsequent read.
        // Simulated by using a ByteArrayInputStream where body bytes follow immediately
        // but the parser should handle it via the read loop.
        String response = "HTTP/1.1 200 OK\r\n"
                        + "Content-Length: 5\r\n"
                        + "\r\n"
                        + "hello";
        SimpleHttpResponseParser parser = new SimpleHttpResponseParser();
        SimpleHttpResponse result = parser.parse(new ByteArrayInputStream(response.getBytes(UTF8)));
        assertNotNull(result);
        byte[] body = result.getBody();
        assertNotNull(body);
        assertArrayEquals("hello".getBytes(UTF8), body);
    }

    @Test
    public void parseResponseWithExtraTrailingBytes() throws IOException {
        // A response where Content-Length is smaller than the bytes available
        // after the headers in the buffer. The parser should take exactly
        // Content-Length bytes and ignore trailing bytes.
        String response = "HTTP/1.1 200 OK\r\n"
                        + "Content-Length: 3\r\n"
                        + "\r\n"
                        + "OK\nEXTRA_DATA_HERE"; // only first 3 bytes ("OK\n") are body
        SimpleHttpResponseParser parser = new SimpleHttpResponseParser();
        SimpleHttpResponse result = parser.parse(new ByteArrayInputStream(response.getBytes(UTF8)));
        assertNotNull(result);
        byte[] body = result.getBody();
        assertNotNull(body);
        assertEquals(3, body.length);
        assertArrayEquals("OK\n".getBytes(UTF8), body);
    }
}

