    @Test
    public void testRedisSsl() throws Exception {
        String host = "localhost";
        int port = 1879;
        String trustedCertificatesPath = "trustedCertificatesPath";
        String trustedCertificatesJksPassword = "trustedCertificatesJksPassword";
        String keyCertChainFilePath = "keyCertChainFilePath";
        String keyFilePath = "keyFilePath";
        String keyFilePassword = "keyFilePassword";
        RedisConnectionConfig redisConnectionConfig = RedisConnectionConfig.Builder.redis(host)
                .withHost(host)
                .withPort(port)
                .withSslEnable(true)
                .withTrustedCertificatesPath(trustedCertificatesPath)
                .withTrustedCertificatesJksPassword(trustedCertificatesJksPassword)
                .withKeyCertChainFilePath(keyCertChainFilePath)
                .withKeyFilePath(keyFilePath)
                .withKeyFilePassword(keyFilePassword)
                .build();

        Assert.assertTrue(redisConnectionConfig.isSslEnable());
        Assert.assertEquals(redisConnectionConfig.getTrustedCertificatesPath(), trustedCertificatesPath);
        Assert.assertEquals(redisConnectionConfig.getTrustedCertificatesJksPassword(), trustedCertificatesJksPassword);
        Assert.assertEquals(redisConnectionConfig.getKeyCertChainFilePath(), keyCertChainFilePath);
        Assert.assertEquals(redisConnectionConfig.getKeyFilePath(), keyFilePath);
        Assert.assertEquals(redisConnectionConfig.getKeyFilePassword(), keyFilePassword);
    }

    /**
     * Test that initSslOptions does not throw NPE when only keyCertChainFilePath is set
     * but keyFilePath is null. The OR condition at line 125 allows entry into the block,
     * but subsequent code assumes both are non-null, causing NPE.
     */
    @Test
    public void testInitSslOptionsWithOnlyKeyCertChainFilePath() throws Exception {
        // Create config with ssl enabled, only keyCertChainFilePath set, keyFilePath is null
        RedisConnectionConfig config = RedisConnectionConfig.Builder.redis("localhost")
                .withSslEnable(true)
                .withKeyCertChainFilePath("/path/to/cert.pem")
                // keyFilePath intentionally NOT set (null)
                .build();

        // Use reflection to call private initSslOptions method
        java.lang.reflect.Method initSslOptions = RedisDataSource.class
                .getDeclaredMethod("initSslOptions", RedisConnectionConfig.class);
        initSslOptions.setAccessible(true);

        // This should NOT throw NullPointerException
        // The correct behavior is to skip the key material block when keyFilePath is null
        Object result = initSslOptions.invoke(null, config);

        // The method should return a non-null SslOptions object (since ssl is enabled)
        Assert.assertNotNull("initSslOptions should return a valid SslOptions", result);
    }

    /**
     * Test that initSslOptions does not throw NPE when only keyFilePath is set
     * but keyCertChainFilePath is null.
     */
    @Test
    public void testInitSslOptionsWithOnlyKeyFilePath() throws Exception {
        // Create config with ssl enabled, only keyFilePath set, keyCertChainFilePath is null
        RedisConnectionConfig config = RedisConnectionConfig.Builder.redis("localhost")
                .withSslEnable(true)
                .withKeyFilePath("/path/to/key.pem")
                // keyCertChainFilePath intentionally NOT set (null)
