        assertEquals("1", request.getParam("a"));

        // normal request
        try {
            HttpEventTask.processPostRequest(new ByteArrayInputStream(("Host: demo.com\r\n" + 
                    "Accept: */*\r\n" + 
                    "Accept-Language: en-us\r\n" + 
                    "Accept-Encoding: gzip, deflate\r\n" + 
                    "Content-Type: application/x-www-form-urlencoded; charset=UTF-8\r\n" + 
                    "Connection: keep-alive\r\n" + 
                    "Content-Length: 10\r\n" + 
                    "\r\n" + 
                    "a=3&b=5的").getBytes()), request);
            assertEquals("3", request.getParam("a"));
            assertEquals("5的", request.getParam("b"));
        } catch (Exception e) {
            assertTrue(false); // should not reach here
        }

        // not supported request
        try {
            HttpEventTask.processPostRequest(new ByteArrayInputStream(("Host: demo.com\r\n" + 
                    "Accept: */*\r\n" + 
                    "Accept-Language: en-us\r\n" + 
                    "Accept-Encoding: gzip, deflate\r\n" + 
                    "Content-Type: application/json\r\n" + 
                    "Connection: keep-alive\r\n" + 
                    "Content-Length: 7\r\n" + 
                    "\r\n" + 
                    "a=1&b=2").getBytes()), request);
            assertTrue(false); // should not reach here
        } catch (RequestException e) {
            assertTrue(e.getStatusCode() == StatusCode.UNSUPPORTED_MEDIA_TYPE);
        }

        // Capacity test
        char[] buf = new char[1024 * 1024];
        Arrays.fill(buf, '&');
        String padding = new String(buf);
        try {
            request = new CommandRequest();
            HttpEventTask.processPostRequest(new ByteArrayInputStream(("Host: demo.com\r\n" + 
                    "Accept: */*\r\n" + 
                    "Accept-Language: en-us\r\n" + 
                    "Accept-Encoding: gzip, deflate\r\n" + 
                    "Content-Type: application/x-www-form-urlencoded\r\n" + 
                    "Connection: keep-alive\r\n" + 
                    "Content-Length: 7\r\n" + 
                    "\r\n" + 
                    padding +
                    "a=1&b=2").getBytes()), request);
            assertEquals(0, request.getParameters().size());
        } catch (Exception e) {
            assertTrue(false);
        }
        try {
            String querystring = "a+=+&b=%E7%9A%84的";
            request = new CommandRequest();
            HttpEventTask.processPostRequest(new ByteArrayInputStream(("Host: demo.com\r\n" + 
                    "Accept: */*\r\n" + 
                    "Accept-Language: en-us\r\n" + 
                    "Accept-Encoding: gzip, deflate\r\n" + 
                    "Content-Type: application/x-www-form-urlencoded\r\n" + 
                    "Connection: keep-alive\r\n" + 
                    "Content-Length: " + (padding.length() + querystring.getBytes().length) + "\r\n" + 
                    "\r\n" + 
                    padding +
                    querystring).getBytes()), request);
            assertEquals(2, request.getParameters().size());
            assertEquals(" ", request.getParam("a "));
            assertEquals("的的", request.getParam("b"));
        } catch (Exception e) {
            assertTrue(false);
        }
    }

    @Before
    public void setUp() {
        // Save default charset config so we can restore it
    }

    @After
    public void tearDown() {
        // Restore default charset
        SentinelConfig.setConfig(SentinelConfig.CHARSET, SentinelConfig.DEFAULT_CHARSET);
    }

    @Test
    public void writeResponseContentLengthShouldMatchConfiguredCharset() throws Exception {
        // Use a charset that is different from platform default charset.
        // ISO-8859-1 maps each code point to exactly one byte, so characters
        // outside its range get replaced with '?' (1 byte each).
        String configuredCharset = "ISO-8859-1";
        SentinelConfig.setConfig(SentinelConfig.CHARSET, configuredCharset);

        // A message containing characters outside ISO-8859-1 range.
        // These Chinese characters are 6 bytes in UTF-8 but become 2 '?' bytes in ISO-8859-1.
        String message = "测试";

        // Calculate what the Content-Length SHOULD be: the byte length of the
        // message when encoded with the configured charset (ISO-8859-1),
        // because that is what PrintWriter actually writes.
        byte[] correctBodyBytes = message.getBytes(Charset.forName(configuredCharset));
        int expectedContentLength = correctBodyBytes.length;

        // Create a byte array output stream to capture what the PrintWriter writes.
        ByteArrayOutputStream baos = new ByteArrayOutputStream();
        PrintWriter pw = new PrintWriter(new OutputStreamWriter(baos, Charset.forName(configuredCharset)));

        // Create an HttpEventTask and use reflection to call the private writeResponse method.
        HttpEventTask task = new HttpEventTask(null);
        Method writeResponseMethod = HttpEventTask.class.getDeclaredMethod(
                "writeResponse", PrintWriter.class, StatusCode.class, String.class);
        writeResponseMethod.setAccessible(true);
        writeResponseMethod.invoke(task, pw, StatusCode.OK, message);

        pw.flush();
        String output = baos.toString(configuredCharset);

        // Parse the Content-Length header from the output.
        int contentLengthHeaderIndex = output.indexOf("Content-Length: ");
        assertTrue("Output should contain Content-Length header", contentLengthHeaderIndex >= 0);
        String contentLengthLine = output.substring(contentLengthHeaderIndex);
        int endOfContentLengthLine = contentLengthLine.indexOf("\r\n");
        String contentLengthValue = contentLengthLine.substring(16, endOfContentLengthLine).trim();
        int declaredContentLength = Integer.parseInt(contentLengthValue);

        // The Content-Length header must match the actual bytes written by PrintWriter.
        // The PrintWriter uses the configured charset (ISO-8859-1), so Content-Length
        // should equal the byte length of the message in ISO-8859-1, NOT in UTF-8.
        assertEquals("Content-Length header (" + declaredContentLength + ") must match the byte length "
                + "of the message body encoded with the configured charset (" + expectedContentLength + "). "
                + "Bug: message.getBytes() uses platform default charset, not the configured charset.",
                expectedContentLength, declaredContentLength);
    }
}

