package com.alibaba.csp.sentinel.cluster.flow.statistic.limit;

import com.alibaba.csp.sentinel.cluster.server.AbstractTimeBasedTest;
import com.alibaba.csp.sentinel.util.TimeUtil;
import org.junit.Test;
import org.mockito.MockedStatic;

import java.util.concurrent.CountDownLatch;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicInteger;

import static org.junit.Assert.*;

public class RequestLimiterTest extends AbstractTimeBasedTest {

    @Test
    public void testTryPassConcurrency() throws InterruptedException {
        try (MockedStatic<TimeUtil> mocked = super.mockTimeUtil()) {
            setCurrentMillis(mocked, System.currentTimeMillis());

            // QPS limit of 10
            int qpsAllowed = 10;
            RequestLimiter limiter = new RequestLimiter(qpsAllowed);

            // Launch many threads concurrently to hit tryPass() simultaneously
            int threadCount = 50;
            CountDownLatch startLatch = new CountDownLatch(1);
            CountDownLatch doneLatch = new CountDownLatch(threadCount);
            AtomicInteger passedCount = new AtomicInteger(0);

            Thread[] threads = new Thread[threadCount];
            for (int i = 0; i < threadCount; i++) {
                threads[i] = new Thread(() -> {
                    try {
                        startLatch.await();
                        if (limiter.tryPass()) {
                            passedCount.incrementAndGet();
                        }
                    } catch (InterruptedException e) {
                        Thread.currentThread().interrupt();
                    } finally {
                        doneLatch.countDown();
                    }
                });
                threads[i].start();
            }

            // Release all threads at once
            startLatch.countDown();
            // Wait for all to complete
            doneLatch.await(5, TimeUnit.SECONDS);

            // The number of threads that passed should NOT exceed the QPS allowed
            // With TOCTOU bug, more threads than qpsAllowed can pass because
            // they all see canPass()=true before any of them call add(1).
            int passed = passedCount.get();
            assertTrue("Expected at most " + qpsAllowed + " to pass, but " + passed
                    + " passed. TOCTOU race condition in tryPass(): "
                    + passed + " > " + qpsAllowed,
                    passed <= qpsAllowed);
        }
    }

    @Test
    public void testRequestLimiter() {
        try (MockedStatic<TimeUtil> mocked = super.mockTimeUtil()) {
            setCurrentMillis(mocked, System.currentTimeMillis());
            RequestLimiter limiter = new RequestLimiter(10);
            limiter.add(3);
            limiter.add(3);
            limiter.add(3);
            assertTrue(limiter.canPass());
            assertEquals(9, limiter.getSum());
            limiter.add(3);
            assertFalse(limiter.canPass());

            // wait a second to refresh the window
            sleep(mocked, 1000);
            limiter.add(3);
            assertTrue(limiter.tryPass());
            assertTrue(limiter.canPass());
            assertEquals(4, limiter.getSum());
        }
    }
}

