    @Test
    public void testCircuitBreakerReusedOnReloadWithSameRule() throws Exception {
        // Load a default rule
        List<DegradeRule> rules = new ArrayList<DegradeRule>();
        DegradeRule rule = new DegradeRule(DefaultCircuitBreakerRuleManager.DEFAULT_KEY)
            .setGrade(CircuitBreakerStrategy.SLOW_REQUEST_RATIO.getType())
            .setCount(50)
            .setTimeWindow(10)
            .setSlowRatioThreshold(0.6)
            .setMinRequestAmount(100)
            .setStatIntervalMs(20000);
        rules.add(rule);
        DefaultCircuitBreakerRuleManager.loadRules(rules);

        // Call getDefaultCircuitBreakers to create circuit breakers for a resource
        String resA = "testResA";
        List<CircuitBreaker> cbsBefore = DefaultCircuitBreakerRuleManager.getDefaultCircuitBreakers(resA);
        assertNotNull(cbsBefore);
        CircuitBreaker cbBefore = cbsBefore.get(0);
        assertNotNull(cbBefore);

        // Reload with a DIFFERENT rule to force actual reload (DynamicSentinelProperty skips equal values)
        // Then reload back with the original rule to test reuse
        List<DegradeRule> differentRules = new ArrayList<DegradeRule>();
        DegradeRule differentRule = new DegradeRule(DefaultCircuitBreakerRuleManager.DEFAULT_KEY)
            .setGrade(CircuitBreakerStrategy.ERROR_RATIO.getType())
            .setCount(0.1d)
            .setTimeWindow(10);
        differentRules.add(differentRule);
        // This must actually trigger reload
        assertTrue("First reload should trigger update", DefaultCircuitBreakerRuleManager.loadRules(differentRules));

        // Now reload with the original rule (same as first load) - this should trigger reload
        // and REUSE existing circuit breakers
        List<DegradeRule> sameRules = new ArrayList<DegradeRule>();
        DegradeRule sameRule = new DegradeRule(DefaultCircuitBreakerRuleManager.DEFAULT_KEY)
            .setGrade(CircuitBreakerStrategy.SLOW_REQUEST_RATIO.getType())
            .setCount(50)
            .setTimeWindow(10)
            .setSlowRatioThreshold(0.6)
            .setMinRequestAmount(100)
            .setStatIntervalMs(20000);
        sameRules.add(sameRule);
        assertTrue("Second reload should trigger update", DefaultCircuitBreakerRuleManager.loadRules(sameRules));

        // After reload, the circuit breakers for resA should be the SAME instances (reused)
        // because the rule is identical. The method getExistingSameCbOrNew should look up
        // existing circuit breakers by the actual resource name, not by rule.getResource() ("*").
        Field cbsField = DefaultCircuitBreakerRuleManager.class.getDeclaredField("circuitBreakers");
        cbsField.setAccessible(true);
        @SuppressWarnings("unchecked")
        Map<String, List<CircuitBreaker>> cbsMap = (Map<String, List<CircuitBreaker>>) cbsField.get(null);

        List<CircuitBreaker> cbsAfter = cbsMap.get(resA);
        assertNotNull("Circuit breakers should still exist for resA after reload", cbsAfter);
        assertSame("Circuit breaker should be REUSED after reload with same rule (identity check), " +
            "but a new one was created instead", cbBefore, cbsAfter.get(0));
    }

    @Test
    public void testLoadRulesUseDifferentCircuitBreakers() throws Exception {
        String resA = "resA";
        String resB = "resB";
        List<CircuitBreaker> cbsForResourceA = DefaultCircuitBreakerRuleManager.getDefaultCircuitBreakers(resA);
        assertNotNull(cbsForResourceA);
        List<CircuitBreaker> cbsForResourceB = DefaultCircuitBreakerRuleManager.getDefaultCircuitBreakers(resB);
        assertNotNull(cbsForResourceB);
        assertNotEquals(cbsForResourceA, cbsForResourceB);
        Field cbsField;
        try {
            cbsField = DefaultCircuitBreakerRuleManager.class.getDeclaredField("circuitBreakers");
        } catch (NoSuchFieldException e) {
            e.printStackTrace();
            throw new Exception();
        }
        cbsField.setAccessible(true);
        Map<String, List<CircuitBreaker>> cbs = (Map<String, List<CircuitBreaker>>) cbsField.get(
            DefaultCircuitBreakerRuleManager.class);
        assertEquals(2, cbs.size());

        List<DegradeRule> rules = new ArrayList<DegradeRule>();
        DegradeRule rule = new DegradeRule(DefaultCircuitBreakerRuleManager.DEFAULT_KEY)
            //rule is different in strategy
            .setGrade(CircuitBreakerStrategy.ERROR_RATIO.getType())
            .setCount(0.1d)
            .setTimeWindow(10)
            .setSlowRatioThreshold(0.6)
            .setMinRequestAmount(100)
            .setStatIntervalMs(20000);
        assertTrue(DegradeRuleManager.isValidRule(rule));
        rules.add(rule);
        DefaultCircuitBreakerRuleManager.loadRules(rules);
        try {
            cbsField = DefaultCircuitBreakerRuleManager.class.getDeclaredField("circuitBreakers");
        } catch (NoSuchFieldException e) {
            e.printStackTrace();
            throw new Exception();
        }
        cbsField.setAccessible(true);
        Map<String, List<CircuitBreaker>> newCbs = (Map<String, List<CircuitBreaker>>) cbsField.get(
            DefaultCircuitBreakerRuleManager.class);
        assertEquals(2, newCbs.size());
        assertNotEquals(cbs, newCbs);

        List<CircuitBreaker> resACbs = newCbs.get(resA);
        assertNotNull(resACbs);
        List<CircuitBreaker> resBCbs = newCbs.get(resB);
        assertNotNull(resBCbs);
        assertNotEquals(resACbs, resBCbs);
    }

}

