import com.alibaba.csp.sentinel.cluster.server.config.ClusterServerConfigManager;
import com.alibaba.csp.sentinel.cluster.server.AbstractTimeBasedTest;
import com.alibaba.csp.sentinel.util.TimeUtil;
import org.junit.Assert;
import org.junit.Before;
import org.junit.Test;
import org.mockito.MockedStatic;

public class GlobalRequestLimiterTest extends AbstractTimeBasedTest {
    @Before
    public void preTest() {
        ClusterServerConfigManager.setMaxAllowedQps(3);
    }

    @Test
    public void testPass() throws InterruptedException {
        try (MockedStatic<TimeUtil> mocked = super.mockTimeUtil()) {
            setCurrentMillis(mocked, System.currentTimeMillis());
            GlobalRequestLimiter.initIfAbsent("user");
            Assert.assertNotNull(GlobalRequestLimiter.getRequestLimiter("user"));
            Assert.assertEquals(3, GlobalRequestLimiter.getMaxAllowedQps("user"), 0.01);
            Assert.assertTrue(GlobalRequestLimiter.tryPass("user"));
            Assert.assertTrue(GlobalRequestLimiter.tryPass("user"));
            Assert.assertTrue(GlobalRequestLimiter.tryPass("user"));
            Assert.assertFalse(GlobalRequestLimiter.tryPass("user"));
            Assert.assertEquals(3, GlobalRequestLimiter.getCurrentQps("user"), 0.01);

            // wait a second to refresh the window
            sleep(mocked, 1000);
            Assert.assertTrue(GlobalRequestLimiter.tryPass("user"));
            Assert.assertTrue(GlobalRequestLimiter.tryPass("user"));
            Assert.assertEquals(2, GlobalRequestLimiter.getCurrentQps("user"), 0.01);
        }
    }

    @Test
    public void testChangeMaxAllowedQps() {
        GlobalRequestLimiter.initIfAbsent("foo");
        Assert.assertEquals(3, GlobalRequestLimiter.getMaxAllowedQps("foo"), 0.01);
        GlobalRequestLimiter.applyMaxQpsChange(10);
        Assert.assertEquals(10, GlobalRequestLimiter.getMaxAllowedQps("foo"), 0.01);
    }

    /**
     * Verify that concurrent calls to initIfAbsent for the same namespace do NOT
     * overwrite each other's RequestLimiter instances. With the TOCTOU bug
     * (containsKey + put), the last writer wins and earlier threads' state is lost.
     * With the fix (putIfAbsent/computeIfAbsent), the first writer's instance survives.
     */
    @Test
    public void testConcurrentInitIfAbsentShouldNotOverwrite() throws Exception {
        // Clear the static map so we start fresh
        java.lang.reflect.Field mapField = GlobalRequestLimiter.class.getDeclaredField("GLOBAL_QPS_LIMITER_MAP");
        mapField.setAccessible(true);
        @SuppressWarnings("unchecked")
        java.util.Map<String, RequestLimiter> map =
            (java.util.Map<String, RequestLimiter>) mapField.get(null);
        map.clear();

        final String namespace = "race-ns-" + System.nanoTime();
        final int threadCount = 50;

        // Use an AtomicInteger to give each thread a unique QPS value.
        // Each call to new RequestLimiter() calls getMaxAllowedQps internally.
        final java.util.concurrent.atomic.AtomicInteger creationCounter =
            new java.util.concurrent.atomic.AtomicInteger(0);

        // We intercept the QPS value by wrapping ClusterServerConfigManager behavior.
        // Each thread will see a different QPS value (100, 200, 300...).
        // The correct behavior: the first thread's QPS (100) should be in the map.
        // The buggy behavior: any thread's QPS could be in the map (last writer wins).
        final java.util.concurrent.CountDownLatch startLatch = new java.util.concurrent.CountDownLatch(1);
        final java.util.concurrent.CountDownLatch doneLatch = new java.util.concurrent.CountDownLatch(threadCount);

        // Pre-populate thread-specific QPS values via namespace configs
        // We set a global default and each thread will get a unique value via the counter
        Thread[] threads = new Thread[threadCount];
        for (int i = 0; i < threadCount; i++) {
            final int index = i;
            threads[i] = new Thread(() -> {
                try {
                    startLatch.await();
                    // Each thread gets a unique QPS value
                    ClusterServerConfigManager.setMaxAllowedQps((index + 1) * 100);
                    GlobalRequestLimiter.initIfAbsent(namespace);
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                } finally {
                    doneLatch.countDown();
                }
            });
            threads[i].start();
        }

        // Release all threads at once to maximize the race window
        startLatch.countDown();
        doneLatch.await(10, java.util.concurrent.TimeUnit.SECONDS);

        // After all threads complete, check the final QPS value.
        // With the fix: the FIRST thread's QPS should be preserved (100.0).
        // With the bug: the LAST writer's QPS is in the map (could be 5000.0 or anything).
        double finalQps = GlobalRequestLimiter.getMaxAllowedQps(namespace);

        // With the TOCTOU bug (containsKey + put), the last writer wins.
        // With the correct implementation (putIfAbsent or computeIfAbsent), the first writer wins.
        // We assert that the first thread's value (100.0) is preserved.
        Assert.assertEquals(
            "Concurrent initIfAbsent must preserve the FIRST thread's RequestLimiter. " +
            "With TOCTOU bug (containsKey+put), the last writer overwrites it. " +
            "Expected first value (100.0) but got " + finalQps,
            100.0, finalQps, 0.01);

        // Cleanup
        map.clear();
    }
}

