package com.alibaba.csp.sentinel.transport.command.http;

import com.alibaba.csp.sentinel.command.CommandCenterProvider;
import com.alibaba.csp.sentinel.transport.CommandCenter;
import com.alibaba.csp.sentinel.transport.command.SimpleHttpCommandCenter;
import org.junit.Assert;
import org.junit.Test;

import java.net.ServerSocket;
import java.lang.reflect.Method;

public class CommandCenterTest {
    @Test
    public void stopCommandCenter(){
        CommandCenter commandCenter =  CommandCenterProvider.getCommandCenter();
        try {
            commandCenter.stop();
        } catch (Exception e) {
            Assert.fail();
        }
    }
    @Test
    public void startCommandCenter(){
        CommandCenter commandCenter =  CommandCenterProvider.getCommandCenter();
        try {
            commandCenter.start();
        } catch (Exception e) {
            Assert.fail();
        }
    }
    @Test
    public void beforeStartCommandCenter(){
        CommandCenter commandCenter =  CommandCenterProvider.getCommandCenter();
        try {
            commandCenter.beforeStart();
        } catch (Exception e) {
            Assert.fail();
        }
    }

    /**
     * Test that getServerSocketFromBasePort sets SO_REUSEADDR BEFORE binding the socket.
     *
     * SO_REUSEADDR must be set before bind() to be effective for port reuse in
     * TIME_WAIT scenarios. If it is set after bind(), it has no effect.
     *
     * The bug: The code does:
     *   ServerSocket server = new ServerSocket(port, backlog);  // binds immediately
     *   server.setReuseAddress(true);                            // too late!
     *
     * The correct pattern is:
     *   ServerSocket server = new ServerSocket();                // unbound
     *   server.setReuseAddress(true);                            // set before bind
     *   server.bind(new InetSocketAddress(port), backlog);       // bind with reuse
     *
     * This test verifies the ordering by checking isBound() at the moment
     * setReuseAddress is called.
     */
    @Test
    public void testServerSocketReuseAddressBeforeBind() throws Exception {
        int testPort = 18739;

        // Reset the test flag
        SimpleHttpCommandCenter.resetTestFlag();

        // Call getServerSocketFromBasePort via reflection
        Method method = SimpleHttpCommandCenter.class.getDeclaredMethod(
                "getServerSocketFromBasePort", int.class);
        method.setAccessible(true);
        ServerSocket result = (ServerSocket) method.invoke(null, testPort);

        Assert.assertNotNull("getServerSocketFromBasePort should not return null", result);
        Assert.assertTrue("The ServerSocket should be bound", result.isBound());
        Assert.assertTrue("SO_REUSEADDR should be set", result.getReuseAddress());
        result.close();

        // The key assertion: setReuseAddress should be called BEFORE bind.
        // In the correct implementation, isBound() should be false when
        // setReuseAddress is called.
        // In the buggy implementation, isBound() is true because new ServerSocket(port, backlog)
        // already binds the socket in the constructor.
        boolean wasBoundBeforeSetReuseAddress = SimpleHttpCommandCenter.getLastIsBoundBeforeSetReuseAddress();
        Assert.assertFalse(
            "SO_REUSEADDR must be set BEFORE bind(). " +
            "isBound() was " + wasBoundBeforeSetReuseAddress + " before setReuseAddress was called, " +
            "meaning the socket was already bound. " +
            "This proves setReuseAddress(true) is called AFTER new ServerSocket(port, backlog) " +
            "which binds immediately. SO_REUSEADDR has no effect on port reuse in TIME_WAIT.",
            wasBoundBeforeSetReuseAddress
        );
    }
}

