            loader.loadInstance(TestInterface.class);
            fail();
        } catch (Exception e) {
            assertTrue(e instanceof SpiLoaderException);
            assertThat(e.getMessage(), containsString("is not subtype of"));
        }

        try {
            loader.loadInstance(TestFourProvider.class);
            fail();
        } catch (Exception e) {
            assertTrue(e instanceof SpiLoaderException);
            assertThat(e.getMessage(), allOf(containsString("is not Provider class of")
                , containsString("check if it is in the SPI configuration file?")));
        }
    }

    @Test
    public void testCloseResourcesWithNullElements() throws Exception {
        // SpiLoader is cached; get a fresh one via a loader instance we create for reflection
        SpiLoader<ProcessorSlot> loader = SpiLoader.of(ProcessorSlot.class);

        // Use reflection to access the private closeResources method
        Method closeResourcesMethod = SpiLoader.class.getDeclaredMethod("closeResources", Closeable[].class);
        closeResourcesMethod.setAccessible(true);

