        Closeable[] closeables = new Closeable[]{null, null};

        // This should NOT throw NPE; it should just skip null elements silently.
        // Pass array as single Object argument for varargs reflection invocation.
        closeResourcesMethod.invoke(loader, (Object) closeables);
    }
}

