package com.alibaba.csp.sentinel.cluster.flow.statistic.limit;

import com.alibaba.csp.sentinel.cluster.server.config.ClusterServerConfigManager;
import com.alibaba.csp.sentinel.cluster.server.AbstractTimeBasedTest;
import com.alibaba.csp.sentinel.util.TimeUtil;
import org.junit.Assert;
import org.junit.Before;
import org.junit.Test;
import org.mockito.MockedStatic;

public class GlobalRequestLimiterTest extends AbstractTimeBasedTest {
    @Before
    public void preTest() {
        ClusterServerConfigManager.setMaxAllowedQps(3);
    }

    @Test
    public void testPass() throws InterruptedException {
        try (MockedStatic<TimeUtil> mocked = super.mockTimeUtil()) {
            setCurrentMillis(mocked, System.currentTimeMillis());
            GlobalRequestLimiter.initIfAbsent("user");
            Assert.assertNotNull(GlobalRequestLimiter.getRequestLimiter("user"));
            Assert.assertEquals(3, GlobalRequestLimiter.getMaxAllowedQps("user"), 0.01);
            Assert.assertTrue(GlobalRequestLimiter.tryPass("user"));
            Assert.assertTrue(GlobalRequestLimiter.tryPass("user"));
            Assert.assertTrue(GlobalRequestLimiter.tryPass("user"));
            Assert.assertFalse(GlobalRequestLimiter.tryPass("user"));
            Assert.assertEquals(3, GlobalRequestLimiter.getCurrentQps("user"), 0.01);

            // wait a second to refresh the window
            sleep(mocked, 1000);
            Assert.assertTrue(GlobalRequestLimiter.tryPass("user"));
            Assert.assertTrue(GlobalRequestLimiter.tryPass("user"));
            Assert.assertEquals(2, GlobalRequestLimiter.getCurrentQps("user"), 0.01);
        }
    }

    @Test
    public void testChangeMaxAllowedQps() {
        GlobalRequestLimiter.initIfAbsent("foo");
        Assert.assertEquals(3, GlobalRequestLimiter.getMaxAllowedQps("foo"), 0.01);
        GlobalRequestLimiter.applyMaxQpsChange(10);
        Assert.assertEquals(10, GlobalRequestLimiter.getMaxAllowedQps("foo"), 0.01);
    }

    /**
     * Verify that applyMaxQpsChange should NOT override per-namespace QPS limits.
     * When multiple namespaces exist, each should maintain its own independent QPS limit.
     * Calling applyMaxQpsChange for one namespace must not override another namespace's limit.
     */
    @Test
    public void testApplyMaxQpsChangeShouldNotOverrideOtherNamespaces() {
        // Initialize two separate namespaces
        GlobalRequestLimiter.initIfAbsent("namespace-a");
        GlobalRequestLimiter.initIfAbsent("namespace-b");

        // Both start with the default QPS from @Before (3)
        Assert.assertEquals(3, GlobalRequestLimiter.getMaxAllowedQps("namespace-a"), 0.01);
        Assert.assertEquals(3, GlobalRequestLimiter.getMaxAllowedQps("namespace-b"), 0.01);

        // Set namespace-b to a different, independent QPS limit (5)
        GlobalRequestLimiter.getRequestLimiter("namespace-b").setQpsAllowed(5);
        Assert.assertEquals(5, GlobalRequestLimiter.getMaxAllowedQps("namespace-b"), 0.01);

        // Apply a QPS change (simulating an update for namespace-a)
        GlobalRequestLimiter.applyMaxQpsChange(10);

        // namespace-a should be updated to 10
        Assert.assertEquals(10, GlobalRequestLimiter.getMaxAllowedQps("namespace-a"), 0.01);

        // namespace-b should KEEP its independent limit of 5, NOT be overridden to 10
        Assert.assertEquals(5, GlobalRequestLimiter.getMaxAllowedQps("namespace-b"), 0.01);
    }
}

