     */
    @Test
    public void testWriteResponseWithNullExceptionShouldNotThrowNPE() throws Exception {
        com.alibaba.csp.sentinel.command.CommandResponse<?> response = 
            com.alibaba.csp.sentinel.command.CommandResponse.ofFailure((Throwable) null);

        // Verify the response state: failure with null exception
        assert !response.isSuccess();
        assert response.getException() == null;

