            io.netty.channel.ChannelHandlerContext.class,
            boolean.class
        );
        writeResponseMethod.setAccessible(true);

        // This should NOT throw NullPointerException.
        // The correct behavior is to handle null exception gracefully.
        writeResponseMethod.invoke(handler, response, mockCtx, false);
    }

    private void processError(String httpRequestStr, String expectedBody) {
        processError(httpRequestStr, BAD_REQUEST, expectedBody);
    }

