package com.alibaba.csp.sentinel.cluster.server.connection;

import java.net.InetSocketAddress;

import org.junit.Test;

import io.netty.channel.Channel;

import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

/**
 * Tests for ConnectionPool resource leak when reconnecting.
 */
public class ConnectionPoolTest {

    @Test
    public void testCreateConnectionClosesOldConnectionOnReconnect() throws Exception {
        ConnectionPool pool = new ConnectionPool();

        // Create two mock channels with the SAME remote address (same key).
        Channel channel1 = mock(Channel.class);
        Channel channel2 = mock(Channel.class);

        InetSocketAddress sameRemoteAddr = new InetSocketAddress("127.0.0.1", 8777);
        InetSocketAddress localAddr = new InetSocketAddress("0.0.0.0", 8787);

        when(channel1.remoteAddress()).thenReturn(sameRemoteAddr);
        when(channel1.localAddress()).thenReturn(localAddr);
        when(channel1.isActive()).thenReturn(true);

        when(channel2.remoteAddress()).thenReturn(sameRemoteAddr);
        when(channel2.localAddress()).thenReturn(localAddr);
        when(channel2.isActive()).thenReturn(true);

        // Create first connection.
        pool.createConnection(channel1);
        assertEquals("Pool should have 1 connection", 1, pool.count());

        // Create second connection with the SAME key (simulating reconnect).
        pool.createConnection(channel2);

        // Pool should still have exactly 1 connection.
        assertEquals("Pool should still have 1 connection", 1, pool.count());

        // The OLD channel (channel1) should have been closed to avoid resource leak.
        verify(channel1, atLeastOnce()).close();

        // Clean up.
        pool.clear();
    }

    @Test
    public void testCreateConnectionDoesNotCloseChannelWhenNoExistingConnection() throws Exception {
        ConnectionPool pool = new ConnectionPool();

        Channel channel1 = mock(Channel.class);
        InetSocketAddress remoteAddr1 = new InetSocketAddress("127.0.0.1", 8777);
        InetSocketAddress localAddr = new InetSocketAddress("0.0.0.0", 8787);

        when(channel1.remoteAddress()).thenReturn(remoteAddr1);
        when(channel1.localAddress()).thenReturn(localAddr);
