package com.alibaba.csp.sentinel.slots.block.flow.controller;

import com.alibaba.csp.sentinel.node.Node;
import com.alibaba.csp.sentinel.node.StatisticNode;
import com.alibaba.csp.sentinel.slots.block.flow.controller.WarmUpRateLimiterController;

import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

import java.lang.reflect.Field;

/**
 * @author CarpenterLee
 */
public class WarmUpRateLimiterControllerTest {

    @Test
    public void testPace() throws InterruptedException {
        WarmUpRateLimiterController controller = new WarmUpRateLimiterController(10, 10, 1000, 3);

        Node node = mock(Node.class);

        when(node.passQps()).thenReturn(100d);
        when(node.previousPassQps()).thenReturn(100d);

        assertTrue(controller.canPass(node, 1));

        // Easily fail in single request testing, so we increase it to 10 requests and test the average time
        long start = System.currentTimeMillis();
        int requests = 10;
        for (int i = 0; i < requests; i++) {
            assertTrue(controller.canPass(node, 1));
        }
        float cost = (System.currentTimeMillis() - start) / 1.0f / requests;
        assertTrue(Math.abs(cost - 100) < 10);
    }

    @Test
    public void testPaceCanNotPass() throws InterruptedException {
        WarmUpRateLimiterController controller = new WarmUpRateLimiterController(10, 10, 10, 3);

        Node node = mock(Node.class);

        when(node.passQps()).thenReturn(100d);
        when(node.previousPassQps()).thenReturn(100d);

        assertTrue(controller.canPass(node, 1));

        assertFalse(controller.canPass(node, 1));
    }

    @Test
    public void testInterruptedExceptionShouldRollbackLatestPassedTime() throws Exception {
        WarmUpRateLimiterController controller = new WarmUpRateLimiterController(10, 10, 1000, 3);

        Node node = mock(Node.class);
        when(node.passQps()).thenReturn(100d);
        when(node.previousPassQps()).thenReturn(100d);

        // First call passes and sets latestPassedTime to current time
        assertTrue(controller.canPass(node, 1));

        // Get the latestPassedTime value after first pass
        Field latestPassedTimeField = WarmUpRateLimiterController.class.getDeclaredField("latestPassedTime");
        latestPassedTimeField.setAccessible(true);
        java.util.concurrent.atomic.AtomicLong latestPassedTime = (java.util.concurrent.atomic.AtomicLong) latestPassedTimeField.get(controller);
        long beforeValue = latestPassedTime.get();

        // Interrupt the current thread so that Thread.sleep will throw InterruptedException immediately
        Thread.currentThread().interrupt();

        // Second call: expectedTime > currentTime (costTime added), so it enters the wait path.
        // latestPassedTime.addAndGet(costTime) is executed first (line 71), then Thread.sleep throws.
        // The catch block is empty, so it falls through to return false.
        // Bug: the costTime added to latestPassedTime is not rolled back.
        assertFalse(controller.canPass(node, 1));

        // Clear the interrupt flag for subsequent assertions
        Thread.interrupted();

        // After InterruptedException, the costTime should be rolled back so that
        // latestPassedTime is the same as before (or close, within a few ms due to timing).
        long afterValue = latestPassedTime.get();
        // The difference should be very small (within a few ms tolerance for timing)
        // Because the correct behavior is to rollback the costTime addition
        long diff = Math.abs(afterValue - beforeValue);
        assertEquals("latestPassedTime should be rolled back on InterruptedException, but was not. " +
                "Before: " + beforeValue + ", After: " + afterValue + ", Diff: " + diff,
                true, diff < 100);
    }
}

