        for (ServerSocket ss : blockedSockets) {
            try { ss.close(); } catch (Exception ignore) {}
        }
        blockedSockets.clear();
    }

    /**
     * Verify that getServerSocketFromBasePort tries each port at most once.
     * With the bug (tryCount/3), the same port is retried 3 times before
     * progressing to the next port, which is inefficient.
     */
    @Test
    public void testNoDuplicatePortAttempts() throws Exception {
        int basePort = 18719;
        ServerSocket[] blockedSockets = new ServerSocket[3];

        // Block basePort, basePort+1, basePort+2
        // So the method must scan to basePort+3 to find a free port
        for (int i = 0; i < 3; i++) {
            blockedSockets[i] = new ServerSocket(basePort + i);
            this.blockedSockets.add(blockedSockets[i]);
        }

        // Call the private method via reflection
        Method method = SimpleHttpCommandCenter.class.getDeclaredMethod(
            "getServerSocketFromBasePort", int.class);
        method.setAccessible(true);
        ServerSocket result = (ServerSocket) method.invoke(null, basePort);

        Assert.assertNotNull("Should find an available port", result);
        try {
            Assert.assertEquals("Should find the next available port (base+3)",
                basePort + 3, result.getLocalPort());

            // The key assertion: each attempted port should be unique
            // (no port should be tried more than once)
            java.util.List<Integer> attempts = SimpleHttpCommandCenter.testPortAttempts;
            Set<Integer> uniqueAttempts = new HashSet<Integer>(attempts);

            Assert.assertEquals("Each port should be tried at most once; "
                + "duplicate attempts indicate tryCount/3 bug",
                attempts.size(), uniqueAttempts.size());
        } finally {
            result.close();
        }
    }

    // Track blocked sockets for cleanup
    private ArrayList<ServerSocket> blockedSockets = new ArrayList<ServerSocket>();
}

